/*
 * A disposable server over what `mistri new --template intake` writes: the template is generated by the real CLI into a
 * folder of e2e/.tmp (inside the checkout, so `@mistriwork/mistri/app` resolves as in a workspace), then served with its own
 * `mistri.json` and database on a port of its own. Nothing here knows the App: it is the starter, as a person gets it.
 */
import { execFileSync } from 'node:child_process';
import { spawn } from './spawned.js';
import { once } from 'node:events';
import { mkdirSync, mkdtempSync, rmSync } from 'node:fs';
import { createServer } from 'node:net';
import { join } from 'node:path';
import { TMP } from './fixtures.js';

export async function startNewIntake() {
  mkdirSync(TMP, { recursive: true });
  const directory = mkdtempSync(join(TMP, 'new-intake-'));
  let child: ReturnType<typeof spawn> | undefined;
  const stop = async () => {
    if (child && child.exitCode === null && child.signalCode === null) {
      const closed = once(child, 'close');
      child.kill('SIGTERM');
      const force = setTimeout(() => child?.kill('SIGKILL'), 5000);
      try {
        await closed;
      } finally {
        clearTimeout(force);
      }
    }
    rmSync(directory, { recursive: true, force: true });
  };
  try {
    const dir = join(directory, 'help-desk');
    execFileSync(
      process.execPath,
      ['--import', 'tsx', 'packages/mistri/src/server/index.ts', 'new', '--template', 'intake', 'Help Desk', dir],
      {
        stdio: 'pipe',
      },
    );
    const reservation = createServer();
    await new Promise<void>((done, reject) => {
      reservation.once('error', reject);
      reservation.listen(0, '127.0.0.1', done);
    });
    const port = (reservation.address() as { port: number }).port;
    await new Promise<void>((done, reject) => reservation.close((error) => (error ? reject(error) : done())));
    child = spawn(
      process.execPath,
      [
        '--import',
        'tsx',
        'packages/mistri/src/server/index.ts',
        '--config',
        join(dir, 'mistri.json'),
        '--app',
        join(dir, 'app.ts'),
        '--port',
        String(port),
      ],
      {
        env: {
          ...process.env,
          DATABASE_URL: '',
          XDG_CONFIG_HOME: join(directory, 'xdg'),
          MISTRI_OPEN: '0',
          BETTER_AUTH_SECRET: 'isolated-new-intake-secret-at-least-thirty-two-chars',
          MISTRI_AUTH_ADMIN_EMAIL: '',
          MISTRI_AUTH_ADMIN_PASSWORD: '',
        },
        stdio: ['ignore', 'pipe', 'pipe'],
      },
    );
    const running = child;
    let log = '';
    await new Promise<void>((done, reject) => {
      const timer = setTimeout(() => reject(new Error(`New intake startup timed out: ${log}`)), 30_000);
      const read = (chunk: unknown) => {
        log += String(chunk);
        if (log.includes('Listening on ')) {
          clearTimeout(timer);
          done();
        }
      };
      running.stdout!.on('data', read);
      running.stderr!.on('data', read);
      running.once('exit', () => {
        clearTimeout(timer);
        reject(new Error(`New intake exited: ${log}`));
      });
    });
    return { origin: `http://127.0.0.1:${port}`, database: join(dir, 'help-desk.db'), directory, stop, log: () => log };
  } catch (error) {
    await stop();
    throw error;
  }
}
